import React, { useEffect, useMemo, useState } from "react";
import "./App.css";
import PondSimulation from "./PondSimulation";
import {
  ApiError,
  api,
  clearSession,
  hasSession,
} from "./api/client";
import type {
  ApiFarm,
  ApiFeeding,
  ApiPond,
  ApiReading,
  ApiUser,
  BootstrapData,
} from "./api/types";
type Language = "en" | "ha" | "yo" | "pcm";

type Track =
  | "Fish Farmer"
  | "Veterinary Doctor"
  | "Seller / Supplier"
  | "Enthusiast"
  | "Individual"
  | "Other";

type Page =
  | "welcome"
  | "auth"
  | "dashboard"
  | "farms"
  | "marketplace"
  | "community"
  | "profile";

type User = {
  name: string;
  email: string;
  phone?: string;
  role: Track | string;
  otherRole?: string;
  guest?: boolean;
};

type Farm = {
  id: string;
  name: string;
  location: string;
};

type Pond = {
  id: string;
  farmId: string;
  name: string;
  population: number;
  length: number;
  width: number;
  status: string;
};

type Feeding = {
  id: string;
  pondId: string;
  amount: number;
  date: string;
};

type Reading = {
  id: string;
  pondId: string;
  temperature: number;
  oxygen: number;
  ph: number;
  level: number;
  turbidityNtu?: number | null;
  date: string;
};

type Listing = {
  id: string;
  name: string;
  category: string;
  price: number;
  description: string;
  seller: string;
  emoji: string;
};

type CommunityGroupId =
  | "general"
  | "farmers"
  | "veterinary"
  | "sellers"
  | "enthusiasts";

type Message = {
  id: string;
  sender: string;
  text: string;
  date: string;
  mine?: boolean;
  role?: string;
  group: CommunityGroupId;
};


type AppData = {
  user: User | null;
  language: Language;
  farms: Farm[];
  ponds: Pond[];
  feedings: Feeding[];
  readings: Reading[];
  listings: Listing[];
  messages: Message[];
};

